import {decodeSpcWithTimeline,SpcError,MAX_SPC_SIZE} from './spc.mjs';
import {createTimelineIndex} from './spc-preview.mjs';
import {packAirCoordinate} from './spc-air.mjs';
function decode(bytes,path,limit){const times={startMs:[],endMs:[],kind:[],laneStart:[],laneEnd:[],airCoordinates:[]};const report=decodeSpcWithTimeline(bytes,path,limit,(i,s,e,k,a,b,air)=>{times.startMs[i]=s;times.endMs[i]=e;times.kind[i]=k;times.laneStart[i]=a;times.laneEnd[i]=b;if(air)times.airCoordinates.push(packAirCoordinate(i,air))});const timeline=Object.fromEntries(Object.entries(times).filter(([k])=>k!=='airCoordinates').map(([k,v])=>[k,Int32Array.from(v)]));timeline.airVersion=1;timeline.airCoordinates=times.airCoordinates;timeline.index=createTimelineIndex(timeline);return {report,timeline}}
self.addEventListener('message',event=>{const m=event.data;if(!m||!Number.isSafeInteger(m.token)||!(m.bytes instanceof ArrayBuffer)||typeof m.lookupPath!=='string')return;try{if(m.bytes.byteLength>MAX_SPC_SIZE)throw new SpcError('input-oversized');const result=decode(new Uint8Array(m.bytes),m.lookupPath,20);const transfers=[...Object.values(result.timeline).filter(ArrayBuffer.isView).map(a=>a.buffer),result.timeline.index.order.buffer,result.timeline.index.tree.buffer];self.postMessage({token:m.token,status:'ok',...result},transfers)}catch(e){self.postMessage({token:m.token,status:'error',errorCode:e instanceof SpcError?e.code:'internal-error'})}});
